def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remainder = bins % item
    distance = np.minimum(remainder, item - remainder)
    return np.where(bins >= item, -distance, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    ratio = bins / item
    fractional_part = ratio - np.floor(ratio)
    return np.where(bins >= item, -fractional_part, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fits = bins >= item
    remainders = np.where(fits, bins % item, 0)
    return np.where(fits, - (remainders ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    ratio = bins / item
